        } else if (update.message().text().equalsIgnoreCase("/usage")) {
            printUsage(update);
        } else if (update.message().text().equalsIgnoreCase("/reset")) {
            resetUserContext(update);
        } else {
            log.warn("Unknown command:" +update.message().text());
        }
    }

    /**
