                        extraBits = 2;
                        repeatOffset = 3;
                        break;
                    case 17: // Repeat 0 short
                        extraBits = 3;
                        repeatOffset = 3;
                        break;
                    case 18: // Repeat 0 long
                        extraBits = 7;
                        repeatOffset = 11;
                        break;
