public class ProxiedPlayer {

    @Getter
    private BedrockServerSession session;
    @Getter
    private BedrockClientSession downstreamSession = null;

    @Getter
    @Setter
    private String accessToken;
    @Getter
    private String refreshToken;
    @Getter
    private KeyPair keyPair;

    @Getter
