    private void createCollection() throws Exception {
        FieldType fieldType1 = FieldType.newBuilder()
            .withName("id")
            .withDescription("chunk identifier")
            .withDataType(DataType.Int64)
            .withPrimaryKey(true)
            .withAutoID(false)
            .build();

        FieldType fieldType2 = FieldType.newBuilder()
