	public static class Entry {
		public final Path path;
		public final BasicFileAttributes metadata;
		public final byte[] data;

		public Entry(Path path, BasicFileAttributes metadata, byte[] data) {
			this.path = path;
			this.metadata = metadata;
			this.data = data;
		}
	}

