        myStderrFilename = stderrFilename;
        myUseShmdata     = useShmArgPassing;
        myMinion         = null;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Transport accept()
        throws IOException
    {
        if (myMinion == null) {
            myMinion = new PythonMinionTransport(myStdinFilename,
                                                 myStdoutFilename,
                                                 myStderrFilename,
                                                 myUseShmdata);
            return myMinion;
        }
        else {
            while (myMinion != null) {
                try {
                    Thread.sleep(1000);
                }
                catch (InterruptedException e) {
                    // Nothing
                }
            }

            // If we get here we have been closed so throw as such
            throw new IOException("Instance is closed");
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void close()
    {
        if (myMinion != null) {
            myMinion.close();
            myMinion = null;
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean isClosed()
    {
        return myMinion == null;
    }

