    @GetMapping("/cart/readByIdUser/{idClient}")
    public ResponseEntity<Object> readCart(@PathVariable UUID idClient){

        Optional<CartModel> cart = cartRepository.findByIdClient(idClient);

        if (cart.isEmpty()){
