            }

            try (BufferedWriter writer = Files.newBufferedWriter(path.resolve("materials.json"))) {
                Constants.GSON.toJson(this.materials, writer);
            }
        } catch (IOException e) {
            LOGGER.error("Failed to save mod storage for {}", this.mod.id());
        }
    }

