            } else if (result == 4 || result == 5) {
                success += 2;
            } else if (result == 6) {
                advantage += 1;
            } else if (result == 7 || result == 8 || result == 9) {
                success += 1;
                advantage += 1;
            } else if (result == 10 || result == 11) {
                advantage += 2;
            } else if (result == 12) {
                triumph += 1;
            }
        }

        for (int i = 0; i < setback; i++) {
            Dice setbackDice = new Dice(6);
