            preparedStatement.setString(1, leaderboard);
            resultSet = preparedStatement.executeQuery();
            if (resultSet.next()) {
                Clob clob = resultSet.getClob("Cache");
                Reader reader = clob.getCharacterStream();
                StringBuilder sb = new StringBuilder();
