            preparedStatement.close();
            conn.close();
        } catch (SQLException ex) {
            Bukkit.getServer().getConsoleSender().sendMessage(ChatColor.AQUA + "[Dleaderboards] " + ChatColor.RED + "Issue while reading Live Cache [code : 03]");
        } catch (IOException ex) {
            return null;
        }
        return cache;
    }

