            return;
        }

        if (!instance.getCore().isSetup() & !args[0].equals("setup") & !args[0].equals("setgameshield") & !args[0].equals("setbackend")) {
            instance.sendMessage(sender, localization.get(locale, "setup.command.required"));
            return;
