            case "setbackend": {
                if (args.length == 1 && !isViaConsole) {
                    javaBackendSelector();
                } else if (args.length == 2) {
                    setJavaBackend(args);
                } else {
                    instance.sendMessage(sender, localization.get(locale, "usage.setbackend"));
