    private void chatEvent(ExecutorBuilder executorBuilder) {
        initials(executorBuilder);

        if (instance.getCore().getRestAPI().isAPIInvalid(msg)) {
            instance.sendMessage(sender, localization.get(locale, "apikey.invalid"));
            return;
