			captures.add(new Piece(Piece.Pieces.BISHOP, color, -1, -1));
		}
		if (queens == 0){
			captures.add(new Piece(Piece.Pieces.QUEEN, color, -1, -1));
		}

		for (int i = 0; i < -(2-rooks); i++){
