			promote(color, Piece.Pieces.KNIGHT);
		}
		for (int i = 0; i < -(2-bishops); i++){
			capture(new Piece(Piece.Pieces.PAWN, color, -1, -1));
			promote(color, Piece.Pieces.BISHOP);
		}
		for (int i = 0; i < -(1-queens); i++){
			capture(new Piece(Piece.Pieces.PAWN, color, -1, -1));
			promote(color, Piece.Pieces.QUEEN);
		}
	}

