                    resultTokens[i] = new Token(tokenMethod.getMethod().process(a));
                }
            }
        }

        List<Token> reduce = reduce(resultTokens);
        if (reduce.size() == 1 || operators.isEmpty()) {
            return reduce.get(0).getVariable();
        }

        return process(reduce, operators);
    }

