    @Override
    public void handlerEvent(MotionEvent event) {
        if (coverAnimationRunning) return;
        float x = event.getRawX();
        float y = event.getY();
        switch (event.getAction()) {
            case MotionEvent.ACTION_DOWN:
                moveSampling.clear();
