    private final static int DOWN_AREA_NONE = -1;
    private final static int DOWN_AREA_MENU = 1;
    private final static int DOWN_AREA_LEFT = 2;
    private final static int DOWN_AREA_RIGHT = 3;

    int vWidth = 1;
