    MetaphorManager(@NonNull Object object) {
        Class<?> clazz = object.getClass();
        MetaphorRes metaphorRes = clazz.getAnnotation(MetaphorRes.class);
        int[] cvIDs = metaphorRes.containerViewIDs();
        if (cvIDs.length > 0) {
            m_containerViewIds = cvIDs;
        }
    }

